args.command:
cd /workspace && P=http://127.0.0.1:42099; B=http://127.0.0.1:3000
login(){ curl -s -o /dev/null --max-time 10 -x $P -c /tmp/$1.jar -H 'Content-Type: application/json' -d "{\"username\":\"$1\",\"password\":\"$1-password\"}" $B/app/login; }
for u in alice bob admin; do login $u; echo -n "$u -> "; curl -s --max-time 10 -x $P -b /tmp/$u.jar $B/app/api/me; echo; done

cd /workspace && P=http://127.0.0.1:42099; B=http://127.0.0.1:3000
login(){ curl -s -o /dev/null --max-time 10 -x $P -c /tmp/$1.jar -H 'Content-Type: application/json' -d "{\"username\":\"$1\",\"password\":\"$1-password\"}" $B/app/login; }
me(){ curl -s -w ' [%{http_code}]' --max-time 10 -x $P -b /tmp/$1.jar $B/app/api/me; }
login alice; echo "alice: $(me alice)"
login bob;   echo "after bob login -> alice: $(me alice)"; echo "bob: $(me bob)"
login admin; echo "after admin login -> alice: $(me alice)"; echo "bob: $(me bob)"; echo "admin: $(me admin)"

cd /workspace && node -e '
const fs=require("fs"); const p="report.md"; let s=fs.readFileSync(p,"utf8");
s=s.replace("bob DELETE of the same id `404 {\"error\":\"order_not_found\"}` (delete is correctly owner-only)",
            "bob DELETE of an alice-owned order returned `404 {\"error\":\"order_not_found\"}` and the owner\u0027s object persisted (delete is correctly owner-only)");
s=s.replace("bob DELETE `404` and the object persisted. The resource declares only the `note` field",
            "bob DELETE of an alice-owned forbidden report returned `404` and the owner\u0027s object persisted. The resource declares only the `note` field");
s=s.replace("No other target was contacted.",
            "No other target was contacted. The full raw request/response log from the evidence run is in `/workspace/evidence.txt`.");
fs.writeFileSync(p,s); console.log("patched");
'
grep -n "DELETE of an alice-owned" report.md; grep -n "evidence.txt" report.md
